<?php require_once __DIR__.'/../../includes/bootstrap.php';require_role('admin');require_once __DIR__.'/../../includes/document_tools.php';$id=(int)($_GET['progress_id']??0);$q=$pdo->prepare("SELECT ph.id_progress,k.tujuan_akhir FROM progress_harian ph JOIN kegiatan k ON k.id_kegiatan=ph.id_kegiatan WHERE ph.id_progress=?");$q->execute([$id]);$r=$q->fetch();if(!$r||!in_array($r['tujuan_akhir'],['lpd','keduanya'],true)){http_response_code(404);exit('LPD tidak tersedia.');}try{$pdf=sipacak_progress_pdf($pdo,$id);sipacak_download_pdf($pdf,'LPD_'.$id.'.pdf');}catch(Throwable $e){http_response_code(422);exit(e($e->getMessage()));}
